/**
 * One-off cleanup: finds auto-created calendar events with 0 attendees and deletes them.
 * Auto-created events are identified by having "*Auto-generated by LMS*" in their description.
 * 
 * Usage: node scratch/cleanup-empty-calendar-events.js [--dry-run]
 */
require('dotenv').config({ path: '.env.local' });
const { Pool } = require('pg');
const { google } = require('googleapis');

const DRY_RUN = process.argv.includes('--dry-run');

async function main() {
  const pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    ssl: process.env.DATABASE_URL?.includes('supabase') ? { rejectUnauthorized: false } : false,
  });

  try {
    // 1. Get calendar config
    const tpRes = await pool.query(
      `SELECT google_calendar_url, google_client_id, google_client_secret, google_refresh_token FROM training_provider LIMIT 1`
    );
    const tp = tpRes.rows[0];

    let calendarId = 'primary';
    const calUrl = tp.google_calendar_url || '';
    if (calUrl) {
      const cidMatch = calUrl.match(/[?&]cid=([^&]+)/);
      if (cidMatch) {
        try { calendarId = Buffer.from(cidMatch[1], 'base64').toString('utf-8'); } catch { calendarId = cidMatch[1]; }
      } else if (calUrl.includes('@')) { calendarId = calUrl; }
    }

    const oauth2Client = new google.auth.OAuth2(tp.google_client_id, tp.google_client_secret, 'https://developers.google.com/oauthplayground');
    oauth2Client.setCredentials({ refresh_token: tp.google_refresh_token });
    const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

    // 2. Fetch events in a wide range (next 90 days)
    const now = new Date();
    const future = new Date();
    future.setDate(future.getDate() + 90);

    console.log(`${DRY_RUN ? '🔍 DRY RUN — ' : ''}Scanning calendar events from ${now.toISOString().slice(0, 10)} to ${future.toISOString().slice(0, 10)}...\n`);

    let pageToken;
    let totalScanned = 0;
    let emptyAutoCreated = [];

    do {
      const eventsRes = await calendar.events.list({
        calendarId,
        timeMin: now.toISOString(),
        timeMax: future.toISOString(),
        singleEvents: true,
        maxResults: 2500,
        pageToken,
      });

      const events = eventsRes.data.items || [];
      totalScanned += events.length;

      for (const evt of events) {
        const attendees = evt.attendees || [];
        const desc = evt.description || '';
        const isAutoCreated = desc.includes('Auto-generated by LMS');

        if (isAutoCreated && attendees.length === 0) {
          const evtDate = evt.start?.dateTime?.slice(0, 10) || evt.start?.date || '';
          emptyAutoCreated.push({
            id: evt.id,
            summary: evt.summary,
            date: evtDate,
          });
        }
      }

      pageToken = eventsRes.data.nextPageToken;
    } while (pageToken);

    console.log(`Scanned ${totalScanned} events. Found ${emptyAutoCreated.length} empty auto-created event(s).\n`);

    if (emptyAutoCreated.length === 0) {
      console.log('✅ Nothing to clean up.');
      return;
    }

    // 3. Delete empty events
    for (const evt of emptyAutoCreated) {
      console.log(`  ${DRY_RUN ? '[WOULD DELETE]' : '[DELETING]'} "${evt.summary}" on ${evt.date} (${evt.id})`);
      if (!DRY_RUN) {
        try {
          await calendar.events.delete({
            calendarId,
            eventId: evt.id,
            sendUpdates: 'none',
          });
        } catch (err) {
          console.error(`    ❌ Failed: ${err.message}`);
        }
      }
    }

    console.log(`\n✅ ${DRY_RUN ? 'Would delete' : 'Deleted'} ${emptyAutoCreated.length} empty event(s).`);
  } finally {
    pool.end();
  }
}

main().catch(err => { console.error('Fatal:', err); process.exit(1); });
